-- Rogue prequest event #Drogerin
-- items: 52008


function event_say(e)
	-- says nothing after you spawn him
end

function event_spawn(e)
	eq.set_timer("appearance",1000);
end


function event_trade(e)
    local item_lib = require("items");
	local qglobals = eq.get_qglobals(e.other);

	if (e.other:Class() == "Rogue") then 
		if (item_lib.check_turn_in(e.trade, {item1 = 52008})) then -- shackle key
			eq.set_timer("depop",6000);
			e.self:SetAppearance(0);
			e.self:TempName("Nichols");
			e.self:QuestSay(e.other, "unlocks his manacles and stands up. As he dusts himself off and stretches out his limbs, he greets you, 'Well met " .. e.other:GetName() .. ". You have my thanks, but more importantly, I think you'll find that assisting our factions comes with great rewards.", {speak_mode = SpeakMode.Emote});
			e.other:Message(MT.Yellow, "You have freed Nichols, completing the second task for the Smuggler's Camp");
				if(qglobals["rog-nichols"] == nil) then
					eq.set_global("rog-nichols","1",5,"F"); --finished sharvahl prisoner quest
				end
		end
	end
end


function event_timer(e)

	if e.timer == "appearance" then
		e.self:SetAppearance(1);
		eq.stop_timer("appearance");
	elseif e.timer == "depop" then
		eq.stop_timer("depop");
		eq.depop();
	end
end

-- items: 13178
function event_say(e)

	local qglobals = eq.get_qglobals(e.other);

	if(e.message:findi("hail")) then
		e.self:Say(string.format("Hail, %s!  Welcome to Fish's Ale. I am Fish Ranamer, owner of the joint.  Come in and have some brew but don't be startin' no trouble or Bruno will bust you open!",e.other:GetName()));
	elseif(e.message:findi("tax collection") and qglobals.tax_collection ~= nil) then
		e.self:Say("Taxes?! Taxes?! Tax me right out of business is what you folks are doing! Take your taxes and get out of my pub! Unless, of course, you care to buy some drinks...?");
		e.other:SummonItem(13178); -- Item: Ranamer's Tax Payment
		e.other:Faction(291,-10,0); -- Faction: Merchants of Qeynos
	end

end

function event_trade(e)

	local item_lib = require("items");
	item_lib.return_items(e.self, e.other, e.trade)

end

